import itertools

n = 10

# Check all sequences with sum of squares <= 20
all_good = []
with_fixed_positions = []
with_c6 = []
with_all = []

for seq in itertools.product([-1, 1], repeat=n):
    seq = list(seq)
    C = {}
    for k in range(1, n):
        C[k] = sum(seq[i] * seq[i+k] for i in range(n-k))
    s = sum(C[k]**2 for k in range(1, n))
    if s <= 20:
        all_good.append((seq, s, C))
        if seq[0] == -1 and seq[8] == 1:
            with_fixed_positions.append((seq, s, C))
        if C[6] == -1:
            with_c6.append((seq, s, C))
        if seq[0] == -1 and seq[8] == 1 and C[6] == -1:
            with_all.append((seq, s, C))

print("Total sequences with sum <= 20:", len(all_good))
print("With seq[0]=-1, seq[8]=1:", len(with_fixed_positions))
print("With C[6]=-1:", len(with_c6))
print("With all constraints:", len(with_all))

if all_good:
    print("\nSome solutions with sum <= 20:")
    for sol in all_good[:5]:
        print(sol)
